static const lv_image_dsc_t kGeneric = {
    .header = {.magic = LV_IMAGE_HEADER_MAGIC, .cf = LV_COLOR_FORMAT_I1, .flags = 0, .w = 128, .h = 128, .stride = 16},
    .data_size = sizeof(kGenericPixels),
    .data = kGenericPixels,
};

const lv_image_dsc_t* AppStoreIconsSource(const char* app_id) {
    if (app_id && std::strcmp(app_id, "app-store") == 0) {
        return &kStore;
    }
    return &kGeneric;
}

const lv_image_dsc_t* AppStoreIconsSource(const AppStoreItem& item) {
    return item.icon ? &item.icon->image : AppStoreIconsSource(nullptr);
}
